const STOCK_DATA={"click":"","hover":"","confirm":"","error":"","drop":"","coin":"","wood":"","metal":"","glass":"","scratch":"","cloth":"","creak":"","zap":"","laser":"","up":"","down":"","alarm":"","meow":"","boom":""};
/* Stock sound effects. Music remains in music.js unchanged. */
const STOCK={buffers:new Map(),pending:new Map(),last:new Map(),active:0,played:0};
function stockDecode(key){
 if(!AU.ctx)return Promise.resolve(null);
 if(STOCK.buffers.has(key))return Promise.resolve(STOCK.buffers.get(key));
 if(STOCK.pending.has(key))return STOCK.pending.get(key);
 const promise=(async()=>{const bytes=Uint8Array.from(atob(STOCK_DATA[key]),c=>c.charCodeAt(0));const b=await AU.ctx.decodeAudioData(bytes.buffer);
 let peak=0;for(let ch=0;ch<b.numberOfChannels;ch++){const d=b.getChannelData(ch);for(let i=0;i<d.length;i++)peak=Math.max(peak,Math.abs(d[i]))}
 const entry={buffer:b,normal:Math.min(3,.75/Math.max(.01,peak))};STOCK.buffers.set(key,entry);return entry})().catch(()=>null);
 STOCK.pending.set(key,promise);return promise}
function stockPlay(key,volume=.25,rate=1,pan=0,limit=1.8){
 if(!save.set.sfxOn||!STOCK_DATA[key])return;auInit();if(!AU.ctx)return;
 const requested=performance.now(),gap=key=='coin'?45:key=='wood'?65:25;if(requested-(STOCK.last.get(key)||-1000)<gap)return;STOCK.last.set(key,requested);
 stockDecode(key).then(entry=>{if(!entry||performance.now()-requested>500||!save.set.sfxOn||STOCK.active>=16)return;
 const ctx=AU.ctx,src=ctx.createBufferSource(),gain=ctx.createGain(),p=ctx.createStereoPanner();src.buffer=entry.buffer;src.playbackRate.value=rate;p.pan.value=clamp(pan,-1,1);
 const duration=Math.min(limit,entry.buffer.duration/rate),now=ctx.currentTime;
 gain.gain.setValueAtTime(volume*entry.normal,now);gain.gain.linearRampToValueAtTime(volume*entry.normal,now+Math.max(.003,duration-.06));gain.gain.linearRampToValueAtTime(0,now+duration);
 src.connect(gain).connect(p).connect(AU.sfx);STOCK.active++;STOCK.played++;src.onended=()=>{STOCK.active--;src.disconnect();gain.disconnect();p.disconnect()};src.start(now);src.stop(now+duration+.01)})}
addEventListener('pointerdown',()=>{if(AU.ctx)Object.keys(STOCK_DATA).forEach(stockDecode)},{once:true});
const SFX={
 click:()=>stockPlay('click',.22),hover:()=>{if(AU.ctx)stockPlay('hover',.08)},
 coin:gold=>stockPlay('coin',gold?.34:.24,gold?1.16:1),
 place:()=>stockPlay('drop',.23),pop:()=>stockPlay('laser',.09,1.3,0,.3),
 thwack:()=>stockPlay('wood',.22),splash:()=>stockPlay('cloth',.15,.8),
 zap:lv=>stockPlay('zap',lv>1?.24:.17),clang:pan=>stockPlay('metal',.27,1,pan),
 boom:()=>stockPlay('boom',.35,1,0,2),crunch:()=>stockPlay('glass',.17,.85),
 die:()=>{if(Math.random()<.2&&(AU.lastMeow||0)<performance.now()-6000){AU.lastMeow=performance.now();stockPlay('meow',.08,.92,0,.8)}else stockPlay('cloth',.12,1.1)},mower:()=>stockPlay('creak',.22,.6,0,2),
 bite:pan=>stockPlay('wood',.13,.85,pan,.28),scratch:pan=>stockPlay('scratch',.13,1.1,pan,.35),
 clank:pan=>stockPlay('metal',.17,.85,pan),haunt:pan=>stockPlay('glass',.06,.6,pan,.3),
 horn:()=>stockPlay('alarm',.2,.8),bad:()=>stockPlay('error',.17),
 fanfare:()=>stockPlay('up',.25,.9),reveal:()=>stockPlay('confirm',.25),
 ominous:()=>stockPlay('meow',.14,.58),lose:()=>stockPlay('down',.24,.8),
 siren:()=>stockPlay('alarm',.2),sting:()=>stockPlay('down',.15,.7),
 plant:()=>stockPlay('drop',.22,1.2),leaf:()=>stockPlay('coin',.2,1.35),
 suck:()=>stockPlay('creak',.2,1.25),meowHappy:()=>stockPlay('meow',.22,1.15),
 meowGrumpy:()=>stockPlay('meow',.18,.7),purr:()=>stockPlay('meow',.07,.6,0,1),
 zombieStart:()=>stockPlay('meow',.12,.6),};
// Meows are rare on purpose: one cat voice at most every ~8 s across the whole game.
function voice(type,pan=0,vol=1){const now=performance.now();if(now-(AU.lastMeow||0)<8000)return;AU.lastMeow=now;const rate={kit:1.4,fat:.6,ath:1.15,mom:1.05,lead:.65,ghost:.55,owner:.7,boss:.48}[type]||.8;
 if(type=='robo'||type=='basin')stockPlay('metal',Math.min(.24,.12*vol),type=='robo'?.85:1,pan);
 else if(type=='vac'||type=='skate')stockPlay('creak',Math.min(.18,.1*vol),.8,pan);
 else stockPlay('meow',Math.min(.2,.11*vol),rate,pan)}
function showAudioCredits(){overlay('<h2>Звуки и авторы</h2><p>Kenney — Interface, Impact, RPG и Digital Audio (CC0).</p><p>«cat meow» — tuberatanka, Freesound (CC0).</p><p>«Blast» — Mike Koenig, SoundBible, CC BY 3.0. Запись укорочена при воспроизведении; громкость настроена для игры.</p><p><a href="https://soundbible.com/538-Blast.html" target="_blank" rel="noopener">Источник Blast</a> · <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener">CC BY 3.0</a></p>',[['Назад',openSettings]])}

